import re
import inspect
import asyncio


async def _await_result(value):
    return await value


def node_input(inputs):
    # 输入数据
    return {'value': [{'name': 'Alice', 'age': '20', 'rating': '5'}, {'name': 'Bob', 'age': '-2', 'rating': '4'}, {'name': 'Chen', 'age': '22', 'rating': '3'}, {'name': 'Alice', 'age': '20', 'rating': '5'}]}


def node_logic(inputs):
    # Python 处理
    value = inputs.get('value')
    items = inputs.get('items', [])
    text = inputs.get('text', '')
    index = inputs.get('index', 0)
    acc = inputs.get('acc', [])
    result = None
    import csv, json
    from pathlib import Path
    accepted, errors, seen = [], [], set()
    for index, row in enumerate(value):
        try:
            name = row['name'].strip()
            age, rating = int(row['age']), int(row['rating'])
            if not name or not 0 < age < 130 or not 1 <= rating <= 5:
                raise ValueError('字段超出有效范围')
            if name in seen:
                raise ValueError('重复提交')
            seen.add(name)
            accepted.append({'name':name,'age':age,'rating':rating})
        except (ValueError, KeyError, TypeError) as exc:
            errors.append({'row':index+1,'error':str(exc)})
    output = Path('artifacts')
    output.mkdir(exist_ok=True)
    with (output/'survey.csv').open('w',newline='',encoding='utf-8') as file:
        writer = csv.DictWriter(file,fieldnames=['name','age','rating'])
        writer.writeheader()
        writer.writerows(accepted)
    (output/'survey.json').write_text(json.dumps(accepted,ensure_ascii=False,indent=2),encoding='utf-8')
    result = {'accepted':len(accepted),'rejected':len(errors),'records':accepted,'errors':errors}
    return {'value': result}


def node_out(inputs):
    # 结果
    return {'value': inputs.get('value', None)}


def run_graph(trace=None, context=None):
    results = {}
    current_node = None
    try:
        current_node = 'input'
        if True:
            results['input'] = node_input({})
        else:
            results['input'] = None
        if trace is not None:
            trace['input'] = results['input']
        current_node = 'logic'
        if results['input'] is not None:
            results['logic'] = node_logic({'value': results['input']['value']})
        else:
            results['logic'] = None
        if trace is not None:
            trace['logic'] = results['logic']
        current_node = 'out'
        if results['logic'] is not None:
            results['out'] = node_out({'value': results['logic']['value']})
        else:
            results['out'] = None
        if trace is not None:
            trace['out'] = results['out']
    except Exception as exc:
        raise RuntimeError(f'节点 {current_node}: {exc}') from exc
    return results


if __name__ == '__main__':
    from pprint import pprint
    pprint(run_graph())
